function read(){try{return JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{return null}}
function write(s){try{localStorage.setItem(STORAGE,JSON.stringify(s))}catch{}}
function initials(n){return String(n||'').trim().split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'PF'}
function money(v){return v===0?'R$ 0,00':`R$ ${Number(v||0).toFixed(2).replace('.',',')}`}
function parseBRDate(value){const [d,m,y]=String(value||'').split('/').map(Number);return d&&m&&y?new Date(y,m-1,d):null}
function formatDateBR(date){return `${String(date.getDate()).padStart(2,'0')}/${String(date.getMonth()+1).padStart(2,'0')}/${date.getFullYear()}`}
function todayKey(){
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
 const y=parts.find(x=>x.type==='year')?.value,m=parts.find(x=>x.type==='month')?.value,d=parts.find(x=>x.type==='day')?.value;
 return `${y}-${m}-${d}`;
}
function todayBR(){return brFromLocalKey(todayKey())}
function localDateKey(date){
 const d=new Date(date);
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);
 const y=parts.find(x=>x.type==='year')?.value,m=parts.find(x=>x.type==='month')?.value,day=parts.find(x=>x.type==='day')?.value;
 return `${y}-${m}-${day}`;
}
function addKeyDays(key,n){
 const [y,m,d]=String(key).split('-').map(Number);
 const base=new Date(Date.UTC(y,m-1,d+n,12,0,0));
 return `${base.getUTCFullYear()}-${String(base.getUTCMonth()+1).padStart(2,'0')}-${String(base.getUTCDate()).padStart(2,'0')}`;
}
function addDays(date,n){return addKeyDays(localDateKey(date),n)}
const FIXED_HOLIDAYS=['01-01','04-21','05-01','09-07','10-12','11-02','11-15','11-20','12-25'];
function easterSunday(year){const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=((h+l-7*m+114)%31)+1;return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function holidayKeys(year){const easter=easterSunday(year),[y,m,d]=easter.split('-').map(Number);const base=new Date(Date.UTC(y,m-1,d));const keys=new Set(FIXED_HOLIDAYS.map(x=>`${year}-${x}`));for(const delta of [-47,-2,0,60]){const dt=new Date(base);dt.setUTCDate(dt.getUTCDate()+delta);keys.add(`${dt.getUTCFullYear()}-${String(dt.getUTCMonth()+1).padStart(2,'0')}-${String(dt.getUTCDate()).padStart(2,'0')}`)}return keys}
function isHolidayKey(key){const year=Number(String(key).slice(0,4));return holidayKeys(year).has(key)}
function weekdayForKey(key){const [y,m,d]=String(key).split('-').map(Number);return new Date(Date.UTC(y,m-1,d)).getUTCDay()}
function timesForDate(key){if(isHolidayKey(key)||weekdayForKey(key)===0)return ['07:00','08:00','09:00','10:00','11:00','12:00'];if(weekdayForKey(key)===6)return ['07:00','08:00','09:00','10:00','11:00','12:00','13:00','14:00'];return TIMES}
function brFromLocalKey(key){const [y,m,d]=String(key).split('-').map(Number);return y&&m&&d?`${String(d).padStart(2,'0')}/${String(m).padStart(2,'0')}/${y}`:''}
function brToLocalKey(value){const [d,m,y]=String(value||'').split('/').map(Number);return d&&m&&y?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:''}
function appointmentKey(a){const key=String(a?.dateKey||'');if(/^\d{4}-\d{2}-\d{2}$/.test(key))return key;return brToLocalKey(a?.date)||''}
function appointmentBR(a){const key=appointmentKey(a);return brFromLocalKey(key)}
function daysFromTodayBR(date){const a=parseBRDate(date),b=parseBRDate(todayBR());if(!a||!b)return 999;a.setHours(12,0,0,0);b.setHours(12,0,0,0);return Math.round((a-b)/86400000)}
function bookingKey(date,time){return `${date}|${time}`}
function getBookingList(bookings,date,time){const byDate=bookings[bookingKey(date,time)];if(byDate)return byDate;return date===todayBR()?(bookings[time]||[]):[]}
function appointmentDateTime(date,time){const d=parseBRDate(date);if(!d)return null;const [h,m]=String(time||'').split(':').map(Number);d.setHours(h||0,m||0,0,0);return d}
function canCancelAppointment(a){const when=appointmentDateTime(a.date,a.time);return !when||((when-new Date())/3600000)>=2}
function daysLate(student){const due=parseBRDate(student.due);if(!due||student.payment==='pago'||student.paymentStatus==='identified')return 0;const today=new Date();today.setHours(0,0,0,0);due.setHours(0,0,0,0);return Math.max(0,Math.floor((today-due)/86400000))}
function daysUntilDue(student){const due=parseBRDate(student.due);if(!due)return 999;const today=new Date();today.setHours(0,0,0,0);due.setHours(0,0,0,0);return Math.ceil((due-today)/86400000)}
function isInadimplente(student){return daysLate(student)>=2}
function canPay(student){const d=daysUntilDue(student);return student.payment!=='pago' && (d<=10 || d<0)}
function waLink(phone){const digits=String(phone||'').replace(/\D/g,'');return `https://wa.me/${digits||RECEPTION_WHATSAPP}`}
function cap(time,teachers){return (teachers||[]).filter(t=>t&&t.active&&Array.isArray(t.slots)&&t.slots.includes(time)).length*4}
function activeAt(time,teachers){return (teachers||[]).filter(t=>t&&t.active&&Array.isArray(t.slots)&&t.slots.includes(time))}
function suggestTeacher(student,time,teachers,assignments){
 const active=activeAt(time,teachers); const counts=HISTORY[student]||{}; const assigned=Object.values(assignments[time]||{});
 return active.filter(t=>assigned.filter(x=>x===t.name).length<4).sort((a,b)=>(counts[b.name]||0)-(counts[a.name]||0))[0]||null;
}

function App(){
 const p=useMemo(()=>read(),[]);
 const [role,setRole]=useState(p?.role||'student');
 const [screen,setScreen]=useState(p?.screen||'home');
 const [student,setStudent]=useState(p?.student||STUDENTS[0]);
 const [teachers,setTeachers]=useState((p?.teachers||TEACHERS).map(t=>({...t,slots:Array.isArray(t.slots)?t.slots:[],active:t.active!==false})));
 const [students,setStudents]=useState((p?.students||STUDENTS).map(s=>({...s,birthday:s.birthday||'',slots:s.slots||[]})));
 const [bookings,setBookings]=useState(p?.bookings||BOOKINGS);
 const [assignments,setAssignments]=useState(p?.assignments||{'18:00':{'Carol Santos':'João Martins','Ana Souza':'Ana Costa','Paula Mendes':'Camila Rocha','Renato Gomes':'João Martins'}});
 const [attendance,setAttendance]=useState(p?.attendance||{});
 const [waitlist,setWaitlist]=useState(p?.waitlist||{});
 const [assessments,setAssessments]=useState(p?.assessments||ASSESSMENTS);
 const [trainingLog,setTrainingLog]=useState(p?.trainingLog||{});
 const [weightHistory,setWeightHistory]=useState(p?.weightHistory||[{id:1,studentId:STUDENTS[0].id,weight:STUDENTS[0].weight,date:todayBR(),time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}]);
 const [notices,setNotices]=useState(p?.notices||[]);
 const [paymentProofs,setPaymentProofs]=useState(p?.paymentProofs||{});
 const [paymentRecords,setPaymentRecords]=useState(p?.paymentRecords||[]);
 const [retentionActions,setRetentionActions]=useState(p?.retentionActions||{});
 const [toast,setToast]=useState('');
 const [modal,setModal]=useState(null);
 const [first,setFirst]=useState(p?.first??false);
 useEffect(()=>write({role,screen,student,teachers,students,bookings,assignments,attendance,waitlist,assessments,trainingLog,weightHistory,notices,paymentProofs,paymentRecords,retentionActions,first}),[role,screen,student,teachers,students,bookings,assignments,attendance,waitlist,assessments,trainingLog,weightHistory,notices,paymentProofs,paymentRecords,retentionActions,first]);
 const notify=m=>{setToast(m);clearTimeout(window.__pf);window.__pf=setTimeout(()=>setToast(''),2600)};
 const switchRole=(nextRole,nextScreen)=>{setRole(nextRole);setScreen(nextScreen);};
 const updateStudent=patch=>{const next={...student,...patch};setStudent(next);setStudents(s=>s.map(x=>x.id===student.id?next:x));};
 const identify=(id,status='identified')=>{setStudents(s=>s.map(x=>x.id===id?{...x,payment:status==='identified'?'pago':'atrasado',paymentStatus:status,status:status==='identified'?'Ativo':'Inadimplente'}:x));if(id===student.id)setStudent(s=>({...s,payment:status==='identified'?'pago':'atrasado',paymentStatus:status,status:status==='identified'?'Ativo':'Inadimplente'}));notify(status==='identified'?'Pagamento identificado. Agendamentos liberados.':'Status do pagamento atualizado.');};
 const submitProof=(proof)=>{setPaymentProofs(x=>({...x,[student.id]:{...proof,submittedAt:new Date().toLocaleString('pt-BR'),status:'pending'}}));updateStudent({paymentStatus:'pending'});addNotice(`${student.name} enviou um comprovante de pagamento para conferência.`);notify('Comprovante enviado. A recepção foi avisada.');};
 const addNotice=(message)=>setNotices(n=>[...n,{id:Date.now(),message,read:false,date:new Date().toLocaleString('pt-BR')}]);
 const currentAppointments=()=>Array.isArray(student.appointments)?student.appointments.map(a=>{const dateKey=appointmentKey(a);return {...a,dateKey,date:brFromLocalKey(dateKey)}}):[];
 const syncAppointments=(items)=>{const normalized=items.map(a=>{const dateKey=appointmentKey(a);return {...a,dateKey,date:brFromLocalKey(dateKey)}});const ordered=normalized.slice().sort((a,b)=>String(a.dateKey).localeCompare(String(b.dateKey))||String(a.time).localeCompare(String(b.time)));const next={...student,appointments:ordered,nextTime:ordered[0]?.time||null,nextDate:ordered[0]?.date||null,appointmentStatus:ordered[0]?.status||null};setStudent(next);setStudents(xs=>xs.map(x=>x.id===student.id?next:x));};
 const book=(time,dateKey=todayKey())=>{const safeDateKey=/^\d{4}-\d{2}-\d{2}$/.test(String(dateKey))?String(dateKey):todayKey();const date=brFromLocalKey(safeDateKey);if(isInadimplente(student)){setScreen('payments');notify('Após 2 dias de atraso, o agendamento fica bloqueado até a confirmação do pagamento.');return}const ap=currentAppointments();if(ap.some(a=>a.dateKey===safeDateKey)){notify('Você já possui 1 agendamento para este dia. Escolha outro dia.');return}const list=getBookingList(bookings,date,time);if(list.includes(student.name)){notify('Você já está agendado neste horário.');return}if(list.length>=cap(time,teachers)){join(time,safeDateKey);return}const key=bookingKey(date,time);setBookings(b=>({...b,[key]:[...getBookingList(b,date,time),student.name]}));syncAppointments([...ap,{id:Date.now(),dateKey:safeDateKey,date,time,status:'Agendado'}]);setScreen('booking');notify(`Horário ${time} reservado para ${date}. O agendamento ficou registrado. Veja seus agendamentos quando quiser.` )};
 const join=(time,dateKey=todayKey())=>{const safeDateKey=/^\d{4}-\d{2}-\d{2}$/.test(String(dateKey))?String(dateKey):todayKey();const date=brFromLocalKey(safeDateKey);const ap=currentAppointments();if(ap.some(a=>a.dateKey===safeDateKey)){notify('Você já possui 1 agendamento para este dia. Escolha outro dia.');return}const existing=(waitlist[time]||[]).find(x=>x.student===student.name&&appointmentKey(x)===safeDateKey);if(existing){setScreen('booking');notify(`Você já está na fila em ${time}, posição ${((waitlist[time]||[]).findIndex(x=>x.student===student.name&&appointmentKey(x)===safeDateKey)+1)}.`);return}const item={id:Date.now(),student:student.name,score:student.frequency,absences:100-student.frequency,cancelNotice:student.frequency,dateKey:safeDateKey,date,createdAt:new Date().toISOString()};setWaitlist(w=>({...w,[time]:[...(w[time]||[]),item]}));setScreen('booking');notify(`Você entrou na fila das ${time}. Sua posição aparece na página de agendamento.`)};
 const confirmBooking=(id)=>{const ap=currentAppointments().map(a=>a.id===id?{...a,status:'Confirmado'}:a);syncAppointments(ap);notify('Agendamento confirmado com sucesso.');};
 const cancel=(id)=>{const ap=currentAppointments();const target=ap.find(a=>a.id===id)||ap[0];if(!target){notify('Nenhum treino para cancelar.');return}if(!canCancelAppointment(target)){notify('Este treino está a menos de 2 horas. O cancelamento fora do prazo conta como falta e precisa ser tratado pela recepção.');return}const key=bookingKey(target.date,target.time);setBookings(b=>({...b,[key]:getBookingList(b,target.date,target.time).filter(n=>n!==student.name)}));const remaining=ap.filter(a=>a.id!==target.id);syncAppointments(remaining);addNotice(`${student.name} cancelou o treino das ${target.time} em ${target.date}. Uma vaga foi liberada.`);notify('Treino cancelado. A vaga foi liberada.')};
 const reschedule=(id,newTime,newDate)=>{const ap=currentAppointments();const target=ap.find(a=>a.id===id)||ap[0];const destinationKey=newDate?.includes('-')?newDate:brToLocalKey(newDate||target?.date);const destinationDate=brFromLocalKey(destinationKey);if(!target||!newTime||!destinationDate)return;if(isInadimplente(student)){notify('Regularize o pagamento para reagendar.');return}if(ap.some(a=>a.id!==target.id&&a.dateKey===destinationKey)){notify('Você já possui outro agendamento para essa data.');return}const destinationList=getBookingList(bookings,destinationDate,newTime);if(destinationList.length>=cap(newTime,teachers)){join(newTime,destinationKey);return}const oldKey=bookingKey(target.date,target.time),newKey=bookingKey(destinationDate,newTime);setBookings(b=>({...b,[oldKey]:getBookingList(b,target.date,target.time).filter(n=>n!==student.name),[newKey]:[...getBookingList(b,destinationDate,newTime),student.name]}));syncAppointments(ap.map(a=>a.id===target.id?{...a,dateKey:destinationKey,date:destinationDate,time:newTime,status:'Agendado'}:a));addNotice(`${student.name} reagendou o treino para ${destinationDate} às ${newTime}.`);notify(`Treino reagendado para ${destinationDate} às ${newTime}.`)};

 if(role==='professor')return <div key="mode-professor"><Professor setRole={setRole} teachers={teachers} students={students} bookings={bookings} assignments={assignments} assessments={assessments} notify={notify} toast={toast}/></div>;
 if(role==='reception')return <ReceptionShell setRole={setRole} setScreen={setScreen} screen={screen} teachers={teachers} setTeachers={setTeachers} students={students} setStudents={setStudents} bookings={bookings} setBookings={setBookings} assignments={assignments} assign={assign} attendance={attendance} setAttendance={setAttendance} waitlist={waitlist} setWaitlist={setWaitlist} assessments={assessments} setAssessments={setAssessments} identify={identify} setModal={setModal} notify={notify} toast={toast} notices={notices} setNotices={setNotices} paymentProofs={paymentProofs} paymentRecords={paymentRecords} setPaymentRecords={setPaymentRecords} retentionActions={retentionActions} setRetentionActions={setRetentionActions}/>;
 return <Student role={role} setRole={setRole} switchRole={switchRole} student={student} screen={screen} setScreen={setScreen} teachers={teachers} bookings={bookings} assignments={assignments} book={book} join={join} cancel={cancel} reschedule={reschedule} confirmBooking={confirmBooking} updateStudent={updateStudent} submitProof={submitProof} assessments={assessments} trainingLog={trainingLog} setTrainingLog={setTrainingLog} weightHistory={weightHistory} setWeightHistory={setWeightHistory} waitlist={waitlist} setWaitlist={setWaitlist} setModal={setModal} notify={notify} toast={toast}/>;
}

function ReceptionShell(props){
 const {setRole,setScreen}=props;
 const safeTeachers=Array.isArray(props.teachers)?props.teachers:TEACHERS;
 const safeStudents=Array.isArray(props.students)?props.students:STUDENTS;
 const safeBookings=props.bookings&&typeof props.bookings==='object'?props.bookings:BOOKINGS;
 const safeAttendance=props.attendance&&typeof props.attendance==='object'?props.attendance:{};
 const safeWaitlist=props.waitlist&&typeof props.waitlist==='object'?props.waitlist:{};
 const safeNotices=Array.isArray(props.notices)?props.notices:[];
 const safeAssessments=Array.isArray(props.assessments)?props.assessments:ASSESSMENTS;
 const safePaymentRecords=Array.isArray(props.paymentRecords)?props.paymentRecords:[];
 const safePaymentProofs=props.paymentProofs&&typeof props.paymentProofs==='object'?props.paymentProofs:{};
 const safeRetention=props.retentionActions&&typeof props.retentionActions==='object'?props.retentionActions:{};
 return <ReceptionBoundary>
  <Reception key="reception-root" {...props} setRole={setRole} screen={['dashboard','agenda','students','teachers','payments','waitlist','reports','settings','professor'].includes(props.screen)?props.screen:'dashboard'} teachers={safeTeachers} students={safeStudents} bookings={safeBookings} attendance={safeAttendance} waitlist={safeWaitlist} notices={safeNotices} assessments={safeAssessments} paymentRecords={safePaymentRecords} paymentProofs={safePaymentProofs} retentionActions={safeRetention}/>
 </ReceptionBoundary>;
}

class ReceptionBoundary extends React.Component{constructor(props){super(props);this.state={error:null}}static getDerivedStateFromError(error){return {error}}componentDidCatch(error){console.error('Power Fit reception error',error)}render(){if(!this.state.error)return this.props.children;return <div className="reception"><header className="reception-top"><button className="icon-btn" onClick={()=>this.props.onBack?.()}><ArrowLeft/></button><Brand dark/><div className="admin-avatar">RF</div></header><main className="admin-pad"><div className="admin-hello"><div><span>PAINEL POWER FIT</span><h1>Recepção</h1><p>A área foi aberta, mas um módulo interno apresentou erro.</p></div></div><div className="card"><h2>Agenda de hoje</h2><p>O aplicativo preservou os dados do aluno. Recarregue para tentar novamente.</p><button className="primary-btn" onClick={()=>location.reload()}>RECARREGAR APLICAÇÃO</button></div></main></div>}}


function Brand({dark=false}){return <div className={'brand '+(dark?'brand-dark':'')}><div className="brand-mark">PF</div><div className="brand-text">POWER <b>FIT</b><small>STUDIO</small></div></div>}
function FirstAccess({onContinue}){const [name,setName]=useState('Carol Santos');const [email,setEmail]=useState('carol.santos@email.com');return <div className="splash"><div className="onboarding"><Brand/><span className="eyebrow">PRIMEIRO ACESSO</span><h1>Seu treino começa aqui.</h1><p>Uma experiência simples para agendar, acompanhar sua evolução e cuidar da sua rotina.</p><div className="welcome-art"><Dumbbell/><Target/><TrendingUp/></div><label>Nome completo<input value={name} onChange={e=>setName(e.target.value)}/></label><label>CPF ou e-mail<input value={email} onChange={e=>setEmail(e.target.value)}/></label><button className="primary-btn full" onClick={()=>onContinue({name,email})}>ENTRAR NO POWER FIT <ChevronRight/></button><small className="demo-note">Modo demonstração • seus dados ficam salvos neste dispositivo</small></div></div>}
function Toast({text}){return <div className="toast"><CheckCircle2/>{text}</div>}
function Student({student,screen,setScreen,teachers,bookings,assignments,book,join,cancel,reschedule,confirmBooking,updateStudent,submitProof,assessments,trainingLog,setTrainingLog,weightHistory,setWeightHistory,waitlist,setWaitlist,notify,toast,setRole,switchRole}){const [menu,setMenu]=useState(false);const overdue=isInadimplente(student);const appointments=student.appointments||[];const sorted=appointments.slice().sort((a,b)=>(appointmentDateTime(a.date,a.time)||0)-(appointmentDateTime(b.date,b.time)||0));const next=sorted[0]||null;const nextTime=next?.time||null;const teacherName=nextTime?(assignments[nextTime]?.[student.name]||null):null;const avatar=student.photo?<img src={student.photo} alt="Foto do perfil"/>:initials(student.name);return <div className="app"><header className="topbar"><Brand/><div className="top-actions"><button className="icon-btn" onClick={()=>setScreen('messages')}><Bell/><i>2</i></button><button className="avatar" onClick={()=>setScreen('profile')}>{avatar}</button><button className="icon-btn" onClick={()=>setMenu(!menu)}><Menu/></button></div></header>{menu&&<div className="menu-pop"><button onClick={()=>{setMenu(false);switchRole('reception','dashboard')}}><Settings/> Visão da recepção</button><button onClick={()=>{setMenu(false);switchRole('professor','home')}}><UserCheck/> Visão do professor</button><button onClick={()=>setScreen('messages')}><Bell/> Notificações</button><button onClick={()=>{localStorage.clear();location.reload()}}><LogOut/> Reiniciar demonstração</button></div>}<main className="mobile-main">{screen==='home'&&<HomeStudent student={student} overdue={overdue} next={next} teacherName={teacherName} setScreen={setScreen}/>} {screen==='booking'&&<Booking student={student} teachers={teachers} bookings={bookings} onBook={book} onJoin={join} setScreen={setScreen}/>} {screen==='appointments'&&<Appointments student={student} appointments={sorted} teacherName={teacherName} onCancel={cancel} onReschedule={reschedule} onConfirm={confirmBooking} waitlist={waitlist} setWaitlist={setWaitlist} setScreen={setScreen} notify={notify}/>} {screen==='training'&&<TrainingScreen setScreen={setScreen}/>} {screen==='evolution'&&<Evolution student={student} assessments={assessments} setScreen={setScreen} weightHistory={weightHistory} setWeightHistory={setWeightHistory} updateStudent={updateStudent} notify={notify}/>} {screen==='payments'&&<PaymentsStudent student={student} onSubmitProof={submitProof} setScreen={setScreen}/>} {screen==='profile'&&<Profile student={student} updateStudent={updateStudent} setScreen={setScreen}/>} {screen==='assessments'&&<Assessments assessments={assessments} student={student} setScreen={setScreen}/>} {screen==='messages'&&<Messages notify={notify} setScreen={setScreen}/>}</main><BottomNav screen={screen} setScreen={setScreen}/>{toast&&<Toast text={toast}/>}</div>}

function HomeStudent({student,overdue,next,teacherName,setScreen}){const lost=Math.max(0,student.initialWeight-student.weight);const nextDate=next?.date||null;const label=nextDate===todayBR()?'HOJE':nextDate?'PRÓXIMO':'SEM AGENDAMENTO';return <><section className="hero"><div className="hero-user"><div className="avatar-lg">{student.photo?<img src={student.photo} alt="Foto"/>:initials(student.name)}</div><div><span>Olá, {student.name.split(' ')[0]}! 👋</span><small>Vamos para mais um treino?</small></div></div><div className="hero-metrics"><div><b>{student.frequency}%</b><span>frequência</span></div><div><b>{student.monthlyWorkouts}</b><span>treinos no mês</span></div><div><b>{lost>=0?'-':''}{Math.abs(lost)} kg</b><span>desde o início</span></div></div></section><div className="page-pad">{overdue&&<div className="alert danger"><AlertCircle/><div><b>Pagamento em atraso</b><span>Seu próximo agendamento está bloqueado até a regularização.</span></div><button onClick={()=>setScreen('payments')}>Regularizar</button></div>}<section className="card featured"><div className="section-head"><span className="label">PRÓXIMO TREINO</span><span className="status-pill">{label}</span></div>{next?<><div className="next-info"><div className="exercise-icon"><Dumbbell/></div><div><h2>Musculação</h2><p><CalendarDays/> {next.date} • <Clock3/> {next.time} • 60 min</p></div></div><button className="primary-btn full" onClick={()=>setScreen('appointments')}>VER MEUS AGENDAMENTOS <ChevronRight/></button></>:<div className="empty"><b>Nenhum treino agendado.</b><span>Escolha seu próximo horário em Agendar.</span><button className="primary-btn full" onClick={()=>setScreen('booking')}>AGENDAR TREINO <CalendarDays/></button></div>}</section><section><div className="section-head title-row"><h3>Acesso rápido</h3></div><div className="quick-grid"><Quick icon={<CalendarDays/>} label="Agendar" onClick={()=>setScreen('booking')}/><Quick icon={<Activity/>} label="Treinos" onClick={()=>setScreen('training')}/><Quick icon={<TrendingUp/>} label="Evolução" onClick={()=>setScreen('evolution')}/><Quick icon={<CreditCard/>} label="Pagamentos" onClick={()=>setScreen('payments')}/></div></section><section className="card evolution-home"><div className="section-head"><h3>Minha evolução</h3><button onClick={()=>setScreen('evolution')}>Ver tudo <ChevronRight/></button></div><div className="weight-line"><div><small>Peso inicial</small><b>{student.initialWeight} kg</b></div><TrendingDown/><div><small>Atual</small><b>{student.weight} kg</b></div><div className="goal"><small>Meta</small><b>{student.goal} kg</b></div></div><div className="progress"><i style={{width:`${Math.min(100,Math.max(5,((student.initialWeight-student.weight)/(student.initialWeight-student.goal))*100))}%`}}/></div><div className="achievement"><Award/><span><b>Você está evoluindo!</b><small>Continue consistente. A próxima conquista está a caminho.</small></span></div></section><section className="card challenge"><div><span className="label">DESAFIO DO MÊS</span><h3>20 treinos em setembro</h3><p>{student.monthlyWorkouts} de 20 concluídos</p></div><div className="challenge-ring">{Math.min(100,student.monthlyWorkouts*5)}%</div></section></div></>}

function Quick({icon,label,onClick}){return <button className="quick" onClick={onClick}>{icon}<b>{label}</b></button>}
function BottomNav({screen,setScreen}){return <nav className="bottom-nav"><Nav active={screen==='home'} icon={<Home/>} label="Início" onClick={()=>setScreen('home')}/><Nav active={screen==='booking'||screen==='appointments'} icon={<CalendarDays/>} label="Agendar" onClick={()=>setScreen('booking')}/><Nav active={screen==='training'} icon={<Dumbbell/>} label="Treinos" onClick={()=>setScreen('training')}/><Nav active={screen==='payments'} icon={<CreditCard/>} label="Pagamento" onClick={()=>setScreen('payments')}/><Nav active={screen==='evolution'||screen==='assessments'} icon={<TrendingUp/>} label="Evolução" onClick={()=>setScreen('evolution')}/></nav>}
function Nav({active,icon,label,onClick}){return <button className={active?'active':''} onClick={onClick}>{icon}<span>{label}</span></button>}
function PageHeader({icon,title,subtitle,setScreen}){return <div className="page-header"><button className="back" onClick={()=>setScreen?.('home')}><ArrowLeft/></button><div className="page-icon">{icon}</div><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div></div>}
function Booking({student,teachers,bookings,onBook,onJoin,setScreen}){
 const [selected,setSelected]=useState(null);
 const todayKeyValue=todayKey();
 const dates=Array.from({length:7},(_,offset)=>{const key=addKeyDays(todayKeyValue,offset);return {key,date:brFromLocalKey(key),label:offset===0?'HOJE':offset===1?'AMANHÃ':offset===2?'EM 2 DIAS':`EM ${offset} DIAS`,offset}});
 const [dateKey,setDateKey]=useState(todayKeyValue);
 const selectedDate=dates.find(d=>d.key===dateKey)||dates[0];
 const date=selectedDate.date;
 const selectedOffset=selectedDate.offset;
 const hasDay=(student.appointments||[]).some(a=>appointmentKey(a)===dateKey);
 const avail=Object.fromEntries(TIMES.map(t=>[t,Math.max(0,cap(t,teachers)-getBookingList(bookings,date,t).length)]));
 const dateBlocked=selectedOffset>2;
 return <div className="page-pad inner">
  <PageHeader setScreen={setScreen} icon={<CalendarDays/>} title="Agendar treino" subtitle="Escolha uma data e um horário para seu treino."/>
  {(student.appointments||[]).length>0&&<section className="card booking-summary"><div className="section-head"><h3>Meus agendamentos</h3><button className="text-btn" onClick={()=>setScreen('appointments')}>Ver todos <ChevronRight/></button></div>{student.appointments.slice().sort((a,b)=>String(appointmentKey(a)).localeCompare(String(appointmentKey(b)))||String(a.time).localeCompare(String(b.time))).map(a=><div className="booking-summary-row" key={a.id}><span><b>{brFromLocalKey(appointmentKey(a))}</b><small>{a.time} • Musculação</small></span><span className="status-pill">{(a.status||'Agendado').toUpperCase()}</span></div>)}</section>}
  <div className="rule-banner"><CalendarDays/><div><b>Regras de agendamento</b><span>Você pode agendar até <b>2 dias de antecedência</b> e somente <b>1 horário por dia</b>.</span></div></div>
  {hasDay&&<div className="alert danger"><AlertCircle/><span>Você já possui um agendamento para esta data. A agenda continua disponível para consulta, mas os horários deste dia estão bloqueados.</span></div>}
  {dateBlocked&&<div className="alert danger"><AlertCircle/><span>Esta data está disponível apenas para visualização. O agendamento só pode ser feito hoje, amanhã ou em 2 dias.</span></div>}
  {isInadimplente(student)&&<div className="alert danger"><AlertCircle/><span>Agendamento bloqueado. Regularize o pagamento e aguarde a confirmação da recepção.</span></div>}
  <div className="date-picker agenda-dates">{dates.map(d=><button key={d.key} disabled={false} className={dateKey===d.key?'active':''} onClick={()=>{setDateKey(d.key);setSelected(null)}}><small>{d.label}</small><b>{d.date}</b></button>)}</div>
  <div className="section-head title-row"><h3 className="section-title">Escolha um horário</h3><button className="text-btn" onClick={()=>setScreen('appointments')}>Meus agendamentos <ChevronRight/></button></div>
  <div className="slots">{timesForDate(dateKey).map(t=>{const full=avail[t]===0;const past=selectedOffset===0 && appointmentDateTime(date,t)<new Date();const unavailable=dateBlocked;const disabled=isInadimplente(student)||hasDay||unavailable||past;return <button key={t} disabled={disabled} className={'slot '+(selected===t?'selected ':'')+(full?'full ':'')+(past?'past ':'')+(unavailable?'unavailable':'')} onClick={()=>setSelected(t)}><b>{t}</b><span>{past?'ENCERRADO':unavailable?'INDISPONÍVEL':full?'LOTADO':`${avail[t]} ${avail[t]===1?'vaga':'vagas'}`}</span>{full&&!past&&!unavailable&&<em>Lista de espera</em>}</button>})}{dateBlocked&&<div className="schedule-closed-note">Horários indisponíveis para agendamento nesta data.</div>}</div>
  {selected&&!dateBlocked&&<div className="card confirm-card"><div><small>HORÁRIO SELECIONADO</small><b>{selected} • 60 min</b><span>{avail[selected]?'Vaga disponível. Confirme para reservar.':'Este horário está lotado. Entre na lista de espera.'}</span></div><button className="primary-btn" onClick={()=>avail[selected]?onBook(selected,dateKey):onJoin(selected,dateKey)}>{avail[selected]?'CONFIRMAR':'ENTRAR NA LISTA'} <Check/></button></div>}
  <div className="card info-card"><ListChecks/><div><b>Agenda completa</b><span>Você pode consultar os próximos 7 dias. Datas além de 2 dias ficam bloqueadas para agendamento.</span></div></div>
 </div>
}

function Appointments({student,appointments,teacherName,onCancel,onReschedule,onConfirm,waitlist,setWaitlist,setScreen,notify}){const [editing,setEditing]=useState(null);const baseKey=todayKey();const dates=[0,1,2].map(n=>addKeyDays(baseKey,n));
 const selectableDates=dates;const entries=Object.entries(waitlist||{}).flatMap(([time,items])=>items.map((x,i)=>x.student===student.name?{...x,time,position:i+1}:null)).filter(Boolean);return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<CalendarDays/>} title="Meus treinos" subtitle="Acompanhe, confirme, cancele ou reagende seus horários."/>{appointments.length?appointments.map(a=><section className="card appointment-card" key={a.id}><div className="appointment-date"><b>{appointmentBR(a)}</b><small>Data do treino</small></div><div className="appointment-body"><span className="status-pill">{(a.status||'Agendado').toUpperCase()}</span><h3>Musculação</h3><p><Clock3/> {a.time} • 60 min</p>{teacherName&&<p><UserCheck/> {teacherName}</p>}</div><div className="action-row three-actions"><button className="primary-btn" onClick={()=>onConfirm(a.id)} title="Confirmar">✓</button><button className="outline-btn" onClick={()=>onCancel(a.id)} title="Cancelar">✕</button><button className="outline-btn" onClick={()=>setEditing(editing===a.id?null:a.id)}>Reagendar</button></div>{editing===a.id&&<div className="reschedule-panel"><label>Nova data<select value={editing?._date||a.date} onChange={e=>setEditing({...a,_date:e.target.value,_time:editing?._time||a.time})}>{selectableDates.map(d=><option key={d} value={d}>{brFromLocalKey(d)}</option>)}</select></label><label>Novo horário<select value={editing?._time||a.time} onChange={e=>setEditing({...a,_date:editing?._date||a.date,_time:e.target.value})}>{TIMES.map(t=><option key={t}>{t}</option>)}</select></label><button className="primary-btn full" onClick={()=>{const d=editing?._date||a.date;const t=editing?._time||a.time;if(d===a.date&&t===a.time){notify('Escolha uma nova data ou horário.');return}onReschedule(a.id,t,d);setEditing(null)}}>SALVAR NOVO HORÁRIO <Check/></button></div>}</section>):<div className="card empty">Você ainda não possui agendamentos.</div>}{entries.map((x,i)=><div className="card wait-box" key={x.time+x.date+i}><div className="wait-title"><div><span className="label">LISTA DE ESPERA</span><h3>{x.time} • {appointmentBR(x)}</h3><p>Você está na <b>{x.position}ª posição</b> da fila.</p></div><span className="status-pill">Aguardando vaga</span></div><div className="wait-actions"><button className="primary-btn" onClick={()=>notify(`Você continua na ${x.position}ª posição da fila.`)}>Aguardar</button><button className="outline-btn" onClick={()=>{setWaitlist(w=>({...w,[x.time]:(w[x.time]||[]).filter(y=>!(y.student===student.name&&appointmentKey(y)===appointmentKey(x)))}));setScreen('booking');notify('Fila cancelada. Escolha outro horário.')}}>Escolher outro horário</button></div></div>)}<div className="card cancel-note"><AlertCircle/><span>Cancelamentos feitos com até <b>2 horas de antecedência</b> não contabilizam falta.</span></div></div>}

function TrainingScreen({setScreen}){
 const groups={
  'Superiores':['Puxada frontal','Remada baixa','Supino máquina','Desenvolvimento de ombros','Elevação lateral','Rosca direta','Tríceps na polia'],
  'Inferiores':['Agachamento livre','Leg press 45°','Cadeira extensora','Cadeira flexora','Elevação pélvica','Panturrilha em pé'],
  'Full body':['Agachamento goblet','Remada baixa','Supino máquina','Elevação lateral','Cadeira flexora','Abdominal máquina']
 };
 const [group,setGroup]=useState('Superiores');
 return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<Dumbbell/>} title="Treinos" subtitle="Consulte os exercícios genéricos disponíveis."/><div className="exercise-tabs">{Object.keys(groups).map(g=><button key={g} className={group===g?'active':''} onClick={()=>setGroup(g)}>{g}</button>)}</div><div className="generic-exercises">{groups[group].map(name=><div className="card generic-exercise" key={name}><div className="exercise-avatar"><Dumbbell/></div><div><b>{name}</b><small>Exercício genérico</small></div></div>)}</div></div>
}

function Evolution({student,assessments,setScreen,weightHistory,setWeightHistory,updateStudent,notify}){
 const [weight,setWeight]=useState(student.weight);
 const [date,setDate]=useState(formatDateBR(new Date()));
 const [time,setTime]=useState(new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}));
 const history=(weightHistory||[]).filter(x=>x.studentId==null||x.studentId===student.id).slice().sort((a,b)=>{const da=appointmentDateTime(a.date,a.time)||0;const db=appointmentDateTime(b.date,b.time)||0;return db-da});
 const addWeight=()=>{const value=Number(String(weight).replace(',','.'));if(!value||value<=0){notify('Informe um peso válido.');return}const entry={id:Date.now(),studentId:student.id,weight:value,date,time};setWeightHistory(x=>[...(x||[]),entry]);updateStudent({weight:value});notify('Nova pesagem registrada.');};
 const lost=Math.max(0,student.initialWeight-student.weight);
 return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<TrendingUp/>} title="Evolução" subtitle="Acompanhe seu peso e histórico de avaliações."/><div className="metric-grid"><Metric icon={<TrendingDown/>} value={`${lost.toFixed(1)} kg`} label="perdidos desde o início"/><Metric icon={<Target/>} value={`${student.goal} kg`} label="meta de peso"/><Metric icon={<Activity/>} value={`${student.frequency}%`} label="frequência"/></div><div className="card weight-entry"><h3>Adicionar nova pesagem</h3><label>Peso atual (kg)<input value={weight} onChange={e=>setWeight(e.target.value)} inputMode="decimal"/></label><div className="two"><label>Data<input type="date" value={date.split('/').reverse().join('-')} onChange={e=>setDate(formatDateBR(new Date(`${e.target.value}T12:00:00`)))}/></label><label>Horário<input type="time" value={time} onChange={e=>setTime(e.target.value)}/></label></div><button className="primary-btn full" onClick={addWeight}>REGISTRAR PESAGEM <Check/></button></div><div className="section-head"><h3 className="section-title">Histórico de peso</h3></div>{history.length?history.map(h=><div className="card history" key={h.id}><span><b>{h.weight} kg</b><small>{h.date} • {h.time}</small></span>{h.weight<=student.weight?<TrendingDown/>:<TrendingUp/>}</div>):<div className="card empty">Nenhuma pesagem registrada.</div>}<div className="section-head"><h3 className="section-title">Avaliações físicas</h3><button onClick={()=>setScreen('assessments')}>Ver histórico <ChevronRight/></button></div>{assessments.filter(a=>a.student===student.name).map(a=><div className="card assessment" key={a.id}><div className="assessment-top"><div><span>{a.date}</span><b>{a.professor}</b></div><span className="status-pill">AVALIAÇÃO</span></div><div className="measure-grid"><Measure l="Peso" v={`${a.weight} kg`}/><Measure l="Cintura" v={`${a.waist} cm`}/><Measure l="Quadril" v={`${a.hip} cm`}/><Measure l="Gordura" v={`${a.bodyFat}%`}/></div></div>)}</div>
}
function Metric({icon,value,label}){return <div className="metric"><div>{icon}</div><b>{value}</b><span>{label}</span></div>}
function Measure({l,v}){return <div><small>{l}</small><b>{v}</b></div>}
function Badge({icon,text}){return <div><span>{icon}</span><b>{text}</b></div>}
function Assessments({assessments,student,setScreen}){return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<FileText/>} title="Avaliações" subtitle="Histórico das suas avaliações físicas."/>{assessments.filter(a=>a.student===student.name).map(a=><div className="card assessment" key={a.id}><div className="assessment-top"><div><span>{a.date}</span><b>{a.professor}</b></div><span className="status-pill">AVALIAÇÃO</span></div><div className="measure-grid"><Measure l="Peso" v={`${a.weight} kg`}/><Measure l="Cintura" v={`${a.waist} cm`}/><Measure l="Quadril" v={`${a.hip} cm`}/><Measure l="Gordura" v={`${a.bodyFat}%`}/></div></div>)}</div>}
function PaymentsStudent({student,onSubmitProof,setScreen}){
 const [fileName,setFileName]=useState('');const [message,setMessage]=useState('');const [method,setMethod]=useState(null);const [copied,setCopied]=useState(false);
 const overdue=isInadimplente(student);const pending=student.paymentStatus==='pending';const d=daysUntilDue(student);const showPay=canPay(student);const pixKey='powerfit@demo.com';
 const copyPix=async()=>{try{await navigator.clipboard.writeText(pixKey);setCopied(true);setTimeout(()=>setCopied(false),1800)}catch{setCopied(true)}};
 const sendProof=()=>{if(!fileName)return;onSubmitProof({fileName,message,method:method||'comprovante'});};
 return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<CreditCard/>} title="Pagamentos" subtitle="Acompanhe seu vencimento e escolha como pagar."/><div className={'payment-status '+(overdue?'late':'ok')}><div>{overdue?<AlertCircle/>:<CheckCircle2/>}</div><span>{overdue?'Pagamento em atraso':d<=10?'Vencimento próximo':'Pagamento em dia'}</span><b>{overdue?`${daysLate(student)} dias de atraso`:d>=0?`Vence em ${d} dias`:'Tudo certo!'}</b></div><div className="card bill"><div><span>Mensalidade</span><h2>{money(student.value)}</h2><p>Vencimento: {student.due}</p></div><Wallet/>{showPay&&<button className="primary-btn full" onClick={()=>setMethod(method==='pix'?null:'pix')}>PAGAR AGORA <ChevronRight/></button>}</div>{showPay&&method&&<div className="card payment-method-card"><div className="method-tabs"><button className={method==='pix'?'active':''} onClick={()=>setMethod('pix')}><QrCode/> PIX</button><button className={method==='card'?'active':''} onClick={()=>setMethod('card')}><CreditCard/> Cartão</button><button className={method==='boleto'?'active':''} onClick={()=>setMethod('boleto')}><FileText/> Boleto</button></div>{method==='pix'&&<div className="pix-area"><h3>Pagamento via PIX</h3><p>Aponte a câmera do celular para o QR Code.</p><img src="./powerfit-pix-qr.png" alt="QR Code PIX"/><div className="pix-key"><span><small>Chave PIX</small><b>{pixKey}</b></span><button onClick={copyPix}>{copied?'Copiada ✓':'Copiar chave'}</button></div></div>}{method==='card'&&<div className="card-form"><h3>Dados do cartão</h3><label>Nome no cartão<input placeholder="Nome completo"/></label><label>Número do cartão<input placeholder="0000 0000 0000 0000"/></label><div className="two"><label>Validade<input placeholder="MM/AA"/></label><label>CVV<input placeholder="123"/></label></div><button className="primary-btn full" onClick={()=>setMethod('proof')}>CONTINUAR PAGAMENTO <Check/></button></div>}{method==='boleto'&&<div className="boleto-area"><FileText/><h3>Boleto bancário</h3><p>O boleto será enviado para o e-mail cadastrado no aplicativo.</p><button className="primary-btn full" onClick={()=>setMethod('proof')}>ENVIAR BOLETO POR E-MAIL</button></div>}{method==='proof'&&<ProofForm fileName={fileName} setFileName={setFileName} message={message} setMessage={setMessage} sendProof={sendProof} pending={pending}/>}</div>}<div className="card proof-card"><div className="proof-title"><FileText/><div><h3>Adicionar comprovante</h3><p>Envie o comprovante do pagamento para a recepção conferir e liberar sua situação financeira.</p></div></div><label className="upload-box"><input type="file" accept="image/*,.pdf" onChange={e=>setFileName(e.target.files?.[0]?.name||'')}/><UploadHint fileName={fileName}/></label><label className="proof-message">Mensagem para a recepção<textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="Ex.: Pagamento realizado via PIX."></textarea></label><button className="primary-btn full" disabled={!fileName} onClick={sendProof}>ENVIAR COMPROVANTE <Check/></button>{pending&&<div className="alert info"><Clock3/><span>Comprovante enviado. Aguarde a confirmação da recepção para liberar novos agendamentos.</span></div>}</div><div className="card plan-card"><div><span>Seu plano</span><b>{student.plan}</b></div><button>Solicitar alteração</button></div></div>
}
function ProofForm({fileName,setFileName,message,setMessage,sendProof,pending}){return <div className="proof-inline"><h3>Comprovante de pagamento</h3><p>Anexe o comprovante após realizar o pagamento.</p><label className="upload-box"><input type="file" accept="image/*,.pdf" onChange={e=>setFileName(e.target.files?.[0]?.name||'')}/><UploadHint fileName={fileName}/></label><label>Mensagem para a recepção<textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="Ex.: Pagamento realizado via PIX."></textarea></label><button className="primary-btn full" disabled={!fileName} onClick={sendProof}>ENVIAR COMPROVANTE <Check/></button>{pending&&<div className="alert info"><Clock3/><span>Comprovante enviado e aguardando conferência.</span></div>}</div>}

function UploadHint({fileName}){return <span className="upload-hint"><FileText/><b>{fileName||'Toque para anexar o comprovante'}</b><small>Imagem ou PDF</small></span>}
function Profile({student,updateStudent,setScreen}){
 const [w,setW]=useState(student.weight);const [g,setG]=useState(student.goal);const [h,setH]=useState(student.height);const [photo,setPhoto]=useState(student.photo||'');const [showData,setShowData]=useState(false);
 const save=()=>updateStudent({weight:Number(String(w).replace(',','.')),goal:Number(String(g).replace(',','.')),height:Number(String(h).replace(',','.')),photo});
 const photoChange=e=>{const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{setPhoto(String(reader.result));updateStudent({photo:String(reader.result)});};reader.readAsDataURL(f)};
 return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<UserRound/>} title="Meu perfil" subtitle="Seus dados e preferências."/><div className="profile-head card"><label className="profile-photo">{photo?<img src={photo} alt="Foto do perfil"/>:initials(student.name)}<span><Camera/></span><input type="file" accept="image/*" onChange={photoChange}/></label><div><h2>{student.name}</h2><span>{student.email||'E-mail não informado'}</span><small>Aluno Power Fit</small></div></div>{showData&&<div id="meus-dados-form" className="card form-card"><h3>Meus dados</h3><label>Nome completo<input value={student.name||''} readOnly/></label><div className="two"><label>E-mail<input value={student.email||'Não informado'} readOnly/></label><label>Telefone<input value={student.phone||'Não informado'} readOnly/></label></div><div className="two"><label>CPF<input value={student.cpf||'Não informado'} readOnly/></label><label>Profissão<input value={student.profession||'Não informado'} readOnly/></label></div><label>Endereço<input value={student.address||'Não informado'} readOnly/></label><label>Altura (m)<input value={h} onChange={e=>setH(e.target.value)}/></label><div className="two"><label>Peso atual<input value={w} onChange={e=>setW(e.target.value)}/></label><label>Meta de peso<input value={g} onChange={e=>setG(e.target.value)}/></label></div><button className="primary-btn full" onClick={save}>SALVAR DADOS <Check/></button></div>}<div className="card menu-list"><button onClick={()=>{setShowData(v=>!v);setTimeout(()=>document.getElementById('meus-dados-form')?.scrollIntoView({behavior:'smooth',block:'start'}),50)}}><UserRound/><span>{showData?'Ocultar meus dados':'Meus dados'}</span><ChevronRight/></button><button onClick={()=>{}}><CreditCard/><span>Meu plano • {student.plan}</span><ChevronRight/></button><button onClick={()=>{}}><Bell/><span>Notificações</span><span className="toggle on">●</span></button><button onClick={()=>window.open(`${waLink('')}?text=${encodeURIComponent('Olá! Preciso de ajuda com meu aplicativo Power Fit.')}`,'_blank')}><MessageCircle/><span>Ajuda e suporte</span><ChevronRight/></button></div></div>
}

function Messages({notify,setScreen}){return <div className="page-pad inner"><PageHeader setScreen={setScreen} icon={<MessageCircle/>} title="Mensagens" subtitle="Comunicação da Power Fit com você."/><div className="card message"><div className="message-icon"><Cake/></div><div><small>Hoje</small><h3>Feliz aniversário! 🎉</h3><p>Que seu novo ciclo venha com muita saúde, energia e conquistas.</p><button className="text-btn" onClick={()=>notify('Mensagem marcada como lida')}>Marcar como lida</button></div></div><div className="card message"><div className="message-icon"><Dumbbell/></div><div><small>Ontem</small><h3>Novo desafio do mês</h3><p>20 treinos em setembro. Bora completar?</p></div></div></div>}
function Professor({setRole,teachers,students,bookings,assignments,assessments,notify,toast}){const [tab,setTab]=useState('today');const me=teachers.find(t=>t.id===1)||teachers[0]||{name:'Professor'};const today=todayBR();const todayBookings=Object.entries(bookings).flatMap(([key,names])=>{if(key.includes('|')){const [date,time]=key.split('|');return date===today?names.map(name=>({name,time})):[]}return names.map(name=>({name,time:key}))});const assigned=[...new Set(todayBookings.filter(x=>assignments[x.time]?.[x.name]===me.name).map(x=>x.name))];return <div className="reception"><header className="reception-top"><button className="icon-btn" onClick={()=>setRole('student')}><ArrowLeft/></button><Brand dark/><div className="admin-avatar">{initials(me.name)}</div></header><main className="admin-pad"><div className="admin-title"><div><span>ÁREA DO PROFESSOR</span><h1>Olá, {me.name.split(' ')[0]} 👋</h1><p>Acompanhe seus alunos, fichas e avaliações.</p></div></div><div className="teacher-tabs"><button className={tab==='today'?'active':''} onClick={()=>setTab('today')}>Hoje</button><button className={tab==='students'?'active':''} onClick={()=>setTab('students')}>Meus alunos</button><button className={tab==='assessments'?'active':''} onClick={()=>setTab('assessments')}>Avaliações</button></div>{tab==='today'&&<><div className="card teacher-hero"><div><span>AGENDA DE HOJE</span><b>{assigned.length} alunos</b><small>Professor: {me.name}</small></div><Dumbbell/></div><h2 className="section-title">Alunos de hoje</h2>{assigned.length?assigned.map(n=><div className="card prof-student" key={n}><div>{initials(n)}</div><span><b>{n}</b><small>Ficha de treino • evolução disponível</small></span><button onClick={()=>notify('Ficha de '+n+' aberta para consulta.')}><ChevronRight/></button></div>):<div className="empty">Nenhum aluno atribuído para hoje.</div>}</>}{tab==='students'&&students.filter(s=>s.status==='Ativo').map(s=><div className="card prof-student" key={s.id}><div>{initials(s.name)}</div><span><b>{s.name}</b><small>{s.frequency}% frequência • {s.weight} kg</small></span><button onClick={()=>notify('Perfil do aluno aberto.')}>Ver</button></div>)}{tab==='assessments'&&assessments.map(a=><div className="card assessment" key={a.id}><div className="assessment-top"><div><span>{a.date}</span><b>{a.student}</b></div><span className="status-pill">{a.professor}</span></div><div className="measure-grid"><Measure l="Peso" v={a.weight+' kg'}/><Measure l="Cintura" v={a.waist+' cm'}/><Measure l="Gordura" v={a.bodyFat+'%'}/><Measure l="Quadril" v={a.hip+' cm'}/></div></div>)}{toast&&<Toast text={toast}/>}</main></div>}
function Reception({setRole,screen,setScreen,teachers,setTeachers,students,setStudents,bookings,setBookings,assignments,assign,attendance,setAttendance,waitlist,setWaitlist,assessments,setAssessments,identify,setModal,notify,toast,notices,setNotices,paymentProofs,paymentRecords,setPaymentRecords,retentionActions,setRetentionActions}){const [open,setOpen]=useState(false);const [selectedTime,setSelectedTime]=useState('18:00');const [search,setSearch]=useState('');const [profTab,setProfTab]=useState(null);const today=students.filter(s=>String(s.birthday||'').endsWith('-09-07'));const month=students.filter(s=>String(s.birthday||'').includes('-09-'));const overdue=students.filter(isInadimplente);return <div className="reception"><header className="reception-top"><button className="icon-btn" onClick={()=>setOpen(!open)}><Menu/></button><button className="brand-home" onClick={()=>setScreen('dashboard')}><Brand dark/></button><div className="top-actions"><button className="icon-btn"><Bell/><i>4</i></button><div className="admin-avatar">RF</div></div></header>{open&&<div className="reception-menu">{[['dashboard','Dashboard',Home],['agenda','Agenda',CalendarDays],['students','Alunos',Users],['teachers','Professores',UserCheck],['payments','Pagamentos',Wallet],['waitlist','Lista de espera',ListChecks],['reports','Relatórios',TrendingUp],['settings','Configurações',Settings],['professor','Visão do professor',UserCheck]].map(([id,l,I])=><button key={id} className={screen===id?'active':''} onClick={()=>{setScreen(id);setOpen(false)}}><I/>{l}</button>)}<button onClick={()=>{setRole('student');setScreen('home')}}><LogOut/> Voltar para aluno</button></div>}{notices.filter(n=>!n.read).length>0&&<div className="reception-notices">{notices.filter(n=>!n.read).map(n=><div key={n.id}><Bell/><span><b>Nova movimentação</b><small>{n.message}</small><time>{n.date}</time></span><button onClick={()=>setNotices(ns=>ns.map(x=>x.id===n.id?{...x,read:true}:x))}>Lido</button></div>)}</div>}<main className="reception-main">{screen==='dashboard'&&<Dashboard students={students} teachers={teachers} bookings={bookings} today={today} overdue={overdue} attendance={attendance} setScreen={setScreen}/>} {screen==='agenda'&&<Agenda selectedTime={selectedTime} setSelectedTime={setSelectedTime} teachers={teachers} bookings={bookings} assignments={assignments} assign={assign} attendance={attendance} setAttendance={setAttendance} notify={notify}/>} {screen==='students'&&<StudentsAdmin students={students} setStudents={setStudents} search={search} setSearch={setSearch} notify={notify} setModal={setModal}/>} {screen==='teachers'&&<TeachersAdmin teachers={teachers} setTeachers={setTeachers} notify={notify} setModal={setModal}/>} {screen==='payments'&&<PaymentsAdmin students={students} identify={identify} setModal={setModal} notify={notify} paymentProofs={paymentProofs} paymentRecords={paymentRecords} setPaymentRecords={setPaymentRecords}/>} {screen==='waitlist'&&<WaitlistAdmin waitlist={waitlist} setWaitlist={setWaitlist} students={students} notify={notify}/>} {screen==='reports'&&<Reports students={students} teachers={teachers} bookings={bookings} retentionActions={retentionActions} setRetentionActions={setRetentionActions}/>} {screen==='settings'&&<SettingsAdmin teachers={teachers} setTeachers={setTeachers}/>} {screen==='professor'&&<Professor setRole={setRole} teachers={teachers} students={students} bookings={bookings} assignments={assignments} assessments={assessments} notify={notify} toast={toast}/>} </main>{toast&&<Toast text={toast}/>}</div>}
function Dashboard({students,teachers,bookings,today,overdue,attendance,setScreen}){const todayKeyValue=todayBR();const total=timesForDate(todayKeyValue).reduce((sum,t)=>sum+getBookingList(bookings,todayKeyValue,t).length,0);const active=teachers.filter(t=>t.active).length;return <div className="admin-pad"><div className="admin-hello"><div><span>PAINEL POWER FIT</span><h1>Boa tarde, Recepção 👋</h1><p>Visão geral da academia em tempo real.</p></div><button className="primary-btn" onClick={()=>setScreen('agenda')}><CalendarDays/> Agenda de hoje</button></div><div className="kpi-grid"><Kpi icon={<CheckCircle2/>} label="Presenças" value={Object.values(attendance).filter(v=>v==='present').length}/><Kpi icon={<UserX/>} label="Faltas" value={Object.values(attendance).filter(v=>v==='absent').length}/><Kpi icon={<Users/>} label="Alunos ativos" value={students.filter(s=>s.status==='Ativo').length}/><Kpi icon={<CalendarDays/>} label="Treinos hoje" value={total}/><Kpi icon={<UserCheck/>} label="Professores ativos" value={active}/><Kpi icon={<AlertCircle/>} label="Inadimplentes" value={overdue.length} danger/></div>{today.length>0&&<div className="admin-alert birthday"><Cake/><div><b>🎉 Aniversariantes de hoje</b><span>{today.map(s=>s.name).join(' • ')}</span></div><button onClick={()=>setScreen('students')}>Ver alunos</button></div>}<section className="admin-section"><div className="section-head"><h2>Operação de hoje</h2><button onClick={()=>setScreen('agenda')}>Abrir agenda <ChevronRight/></button></div><div className="mini-agenda">{timesForDate(todayKeyValue).filter((_,i)=>i<5).map(t=>{const c=getBookingList(bookings,todayKeyValue,t).length;const capacity=cap(t,teachers);return <button key={t} onClick={()=>setScreen('agenda')}><b>{t}</b><span>{c}/{capacity}</span><i style={{width:`${capacity?Math.min(100,c/capacity*100):0}%`}}/></button>})}</div></section><section className="admin-section"><div className="section-head"><h2>Alertas que precisam de atenção</h2></div><div className="alert-list"><button onClick={()=>setScreen('payments')}><AlertCircle/><span><b>{overdue.length} pagamentos em atraso</b><small>Identifique ou entre em contato com os alunos.</small></span><ChevronRight/></button><button onClick={()=>setScreen('waitlist')}><ListChecks/><span><b>6 alunos na lista de espera</b><small>Uma vaga pode ser liberada a qualquer momento.</small></span><ChevronRight/></button><button onClick={()=>setScreen('students')}><TrendingDown/><span><b>5 alunos com queda de frequência</b><small>O sistema recomenda uma ação de retenção.</small></span><ChevronRight/></button></div></section><section className="admin-section"><div className="section-head"><h2>Saúde da academia</h2><span>Setembro</span></div><div className="health-grid"><div><small>Frequência média</small><b>79%</b><em>+4,2%</em></div><div><small>Retenção</small><b>92%</b><em>+1,8%</em></div><div><small>Satisfação</small><b>4,7/5</b><em>+0,3</em></div></div></section></div>}
function Kpi({icon,label,value,danger}){return <div className={'kpi '+(danger?'danger':'')}><div>{icon}</div><span>{label}</span><b>{value}</b></div>}
function Agenda({selectedTime,setSelectedTime,teachers,bookings,assignments,assign,attendance,setAttendance,notify}){const today=todayBR();const dayTimes=timesForDate(today);const list=getBookingList(bookings,today,selectedTime);const available=activeAt(selectedTime,teachers);return <div className="admin-pad"><div className="admin-title"><div><span>AGENDA</span><h1>Agenda • {todayBR()}</h1><p>Agenda por horário. Clique para abrir os alunos.</p></div></div><div className="time-strip">{dayTimes.map(t=><button className={selectedTime===t?'active':''} key={t} onClick={()=>setSelectedTime(t)}><b>{t}</b><span>{getBookingList(bookings,today,t).length}/{cap(t,teachers)}</span></button>)}</div><div className="slot-summary"><div><span>Horário selecionado</span><b>{selectedTime}</b></div><div><span>Ocupação</span><b>{list.length}/{cap(selectedTime,teachers)}</b></div><div><span>Professores</span><b>{available.length}</b></div></div><div className="admin-note"><ShieldCheck/><span><b>Distribuição inteligente:</b> o sistema sugere o professor disponível com maior histórico de treinos com cada aluno, respeitando o limite de 4.</span></div><section className="student-bookings"><div className="section-head"><h2>{list.length} alunos agendados</h2><span>{selectedTime}</span></div>{list.length===0?<div className="empty">Nenhum agendamento neste horário.</div>:list.map(name=>{const suggestion=suggestTeacher(name,selectedTime,teachers,assignments);const selected=assignments[selectedTime]?.[name]||suggestion?.name;const a=attendance[`${selectedTime}-${name}`];const counts=HISTORY[name]||{};return <div className="booking-row" key={name}><div className="student-mini"><div>{initials(name)}</div><span><b>{name}</b><small>Histórico: {selected||'sem professor'}</small></span></div><div className="suggestion"><small>SUGESTÃO</small><b>{suggestion?.name||'Sem disponibilidade'}</b><span>{suggestion?`${counts[suggestion.name]||0} treinos com este aluno`:''}</span></div><div className="prof-select"><label>Direcionar para</label><select value={selected||''} onChange={e=>assign(selectedTime,name,e.target.value)}>{available.map(t=><option key={t.id} value={t.name}>{t.name} • {counts[t.name]||0}x</option>)}</select></div><div className="attendance-inline"><span className={a==='present'?'present':a==='absent'?'absent':'pending'}>{a==='present'?'Presente':a==='absent'?'Falta':'Pendente'}</span><button onClick={()=>setAttendance(x=>({...x,[`${selectedTime}-${name}`]:'present'}))} disabled={!canMark(selectedTime)}><Check/></button><button onClick={()=>setAttendance(x=>({...x,[`${selectedTime}-${name}`]:'absent'}))} disabled={!canMark(selectedTime)}><X/></button></div></div>})}</section><div className="admin-foot-note"><Clock3/> Presença/falta fica disponível quando o horário estiver dentro da janela de atendimento informada pela academia.</div></div>}
function canMark(time){return time==='18:00'}
function ProfessorAdmin({students,teachers,bookings,assignments,attendance,setScreen}){const today=todayBR();const myName='João Martins';const myBookings=Object.entries(bookings).flatMap(([key,names])=>{if(key.includes('|')){const [date,time]=key.split('|');return date===today?names.map(name=>({name,time})):[]}return names.map(name=>({name,time:key}))}).filter(x=>assignments[x.time]?.[x.name]===myName);return <div className="admin-pad"><div className="admin-title"><div><span>PROFESSOR</span><h1>Visão do professor</h1><p>Alunos atribuídos e acompanhamento do treino.</p></div></div><div className="card"><h3>Agenda de hoje • {today}</h3>{myBookings.length?myBookings.map(x=><div className="booking-row" key={x.time+x.name}><div className="student-mini"><div>{initials(x.name)}</div><span><b>{x.name}</b><small>{x.time} • Musculação</small></span></div><span className="status-pill">{attendance[`${x.time}-${x.name}`]==='present'?'PRESENTE':attendance[`${x.time}-${x.name}`]==='absent'?'FALTA':'PENDENTE'}</span></div>):<div className="empty">Nenhum aluno atribuído para hoje.</div>}</div><button className="primary-btn" onClick={()=>setScreen('dashboard')}>Voltar ao painel</button></div>}
function StudentsAdmin({students,setStudents,search,setSearch,notify,setModal}){const [sel,setSel]=useState(null);const filtered=students.filter(s=>s.name.toLowerCase().includes(search.toLowerCase()));return <div className="admin-pad"><div className="admin-title"><div><span>ALUNOS</span><h1>Gestão de alunos</h1><p>Cadastro completo, evolução e avaliações.</p></div><button className="primary-btn" onClick={()=>setModal('newStudent')}><Plus/> Novo aluno</button></div><div className="search"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar aluno..."/></div><div className="student-list-admin">{filtered.map(s=><button key={s.id} onClick={()=>setSel(s.id)} className="admin-student-card"><div>{initials(s.name)}</div><span><b>{s.name}</b><small>{s.plan} • {s.frequency}% frequência</small></span><em className={isInadimplente(s)?'red':''}>{isInadimplente(s)?'Inadimplente':'Em dia'}</em><ChevronRight/></button>)}</div>{sel&&<StudentDrawer student={students.find(x=>x.id===sel)} onClose={()=>setSel(null)} setStudents={setStudents} notify={notify}/>}</div>}
function StudentDrawer({student,onClose,setStudents,notify}){const [plan,setPlan]=useState(student.plan);return <div className="drawer-back"><div className="drawer"><button className="drawer-close" onClick={onClose}><X/></button><div className="drawer-head"><div>{initials(student.name)}</div><h2>{student.name}</h2><span>{student.email||'aluno@powerfit.com'}</span></div><div className="profile-data-grid"><Data label="Telefone" value={student.phone||'Não informado'}/><Data label="CPF" value={student.cpf||'Não informado'}/><Data label="Endereço" value={student.address||'Não informado'}/><Data label="Profissão" value={student.profession||'Não informado'}/></div><div className="drawer-metrics"><div><b>{student.weight}</b><small>kg</small></div><div><b>{student.frequency}%</b><small>frequência</small></div><div><b>{student.monthlyWorkouts}</b><small>treinos/mês</small></div></div><label>Modalidade<select value={plan} onChange={e=>{setPlan(e.target.value);setStudents(xs=>xs.map(x=>x.id===student.id?{...x,plan:e.target.value}:x));notify('Modalidade atualizada.')}}><option>Plano Mensal</option><option>TotalPass</option><option>Wellhub</option><option>Plano Trimestral</option></select></label><div className="card drawer-section"><h3>Histórico de evolução</h3><p>Peso inicial {student.initialWeight} kg → atual {student.weight} kg • meta {student.goal} kg • frequência {student.frequency}%.</p></div><div className="card drawer-section"><h3>Avaliações</h3><p>Histórico de avaliações físicas disponível para consulta e acompanhamento do aluno.</p></div><div className="drawer-actions"><button onClick={()=>notify('Mensagem enviada para o aluno.')}>Enviar mensagem</button><button onClick={()=>notify('Ficha de treino aberta para edição.')}>Ficha de treino</button><button onClick={()=>notify('Aluno marcado para acompanhamento.')}>Acompanhar retenção</button></div><div className="audit">Cadastro e dados cadastrais disponíveis para a recepção.</div></div></div>}
function Data({label,value}){return <div className="data-item"><small>{label}</small><b>{value}</b></div>}
function TeachersAdmin({teachers,setTeachers,notify,setModal}){const today=new Date();const alerts=teachers.filter(t=>t.contractType==='CLT'&&t.hireDate).map(t=>{const h=new Date(t.hireDate);const milestones=[3,6].map(m=>new Date(h.getFullYear(),h.getMonth()+m,h.getDate()));const upcoming=milestones.map((d,i)=>({date:d,month:i===0?3:6})).filter(x=>x.date>=today).sort((a,b)=>a.date-b.date)[0];const days=upcoming?Math.ceil((upcoming.date-today)/86400000):999;return {...t,upcoming,days}}).filter(t=>t.upcoming&&t.days>=0&&t.days<=7);return <div className="admin-pad"><div className="admin-title"><div><span>PROFESSORES</span><h1>Equipe e escala</h1><p>Professores e estagiários, contratação e disponibilidade.</p></div><button className="primary-btn" onClick={()=>setModal('newTeacher')}><Plus/> Novo professor</button></div>{teachers.map(t=><div className="teacher-card" key={t.id}><div className={'teacher-avatar '+(!t.active?'off':'')}>{initials(t.name)}</div><div className="teacher-info"><b>{t.name}</b><span>{t.role||'Professor'} • {t.active?'Ativo':'Inativo'} • {t.slots.length} horários</span><div className="chips">{t.slots.map(x=><i key={x}>{x}</i>)}</div>{t.hireDate&&<small>Contratação: {t.hireDate} • CLT: {t.contractType==='CLT'?'Sim':'Não'}</small>}</div><button className={'switch '+(t.active?'on':'')} onClick={()=>setTeachers(ts=>ts.map(x=>x.id===t.id?{...x,active:!x.active}:x))}><span/></button></div>)}<div className="card capacity-explainer"><Users/><div><b>Capacidade dinâmica</b><span>4 alunos por professor e vagas recalculadas conforme a escala.</span></div></div>{alerts.length>0&&<div className="card experience-alert"><Clock3/><div><b>⚠️ Período de experiência próximo</b>{alerts.map(t=><span key={t.id}>{t.name} completa {t.upcoming.month} meses de contrato em até {t.days} dias.</span>)}</div></div>}<div className="card experience-alert muted-alert"><Clock3/><div><b>Alertas de experiência</b><span>Para CLT, o sistema avisa na semana de completar 3 meses e novamente ao completar 6 meses.</span></div></div></div>}
function PaymentsAdmin({students,identify,setModal,notify,paymentProofs,paymentRecords,setPaymentRecords}){const overdue=students.filter(isInadimplente);const addRecord=(data)=>{setPaymentRecords(r=>[{id:Date.now(),...data,date:new Date().toLocaleString('pt-BR')},...r]);notify('Pagamento registrado. O atendimento mais recente ficou no topo.');};return <div className="admin-pad"><div className="admin-title"><div><span>FINANCEIRO</span><h1>Pagamentos</h1><p>Mensalidades, comprovantes e atendimentos presenciais.</p></div><button className="primary-btn" onClick={()=>setModal('payment')}><Plus/> Inserir pagamentos</button></div>{Object.keys(paymentProofs||{}).length>0&&<div className="card proof-reception-alert"><FileText/><div><b>Comprovantes enviados</b><span>Há comprovantes aguardando conferência na recepção.</span></div></div>}<div className="finance-kpis"><Kpi icon={<Wallet/>} label="Recebido" value="R$ 18.450"/><Kpi icon={<AlertCircle/>} label="Em aberto" value="R$ 2.398" danger/><Kpi icon={<UserX/>} label="Inadimplentes" value={overdue.length} danger/></div>{students.map(s=>{const status=s.paymentStatus|| (s.payment==='pago'?'identified':'not_identified');return <div className="payment-row" key={s.id}><div>{initials(s.name)}</div><span><b>{s.name}</b><small>{s.plan} • {money(s.value)} • vence {s.due}{paymentProofs?.[s.id]?' • comprovante enviado':''}</small></span><select value={status} onChange={e=>identify(s.id,e.target.value)}><option value="identified">Identificado</option><option value="not_identified">Não identificado</option><option value="bank_instability">Instabilidade bancária</option></select></div>})}<div className="card payment-history"><h3>Atendimentos registrados</h3>{paymentRecords.length?paymentRecords.map(r=><div key={r.id}><span><b>{r.name}</b><small>{r.type} • {r.value==='0'?'R$ 0,00':money(Number(r.value))}</small></span><time>{r.date}</time></div>):<p>Nenhum atendimento presencial registrado ainda.</p>}</div></div>}
function WaitlistAdmin({waitlist,setWaitlist,students,notify}){const all=Object.entries(waitlist).flatMap(([time,items])=>items.map((x,i)=>({...x,time,position:i+1}))).sort((a,b)=>b.score-a.score);const call=(x)=>{const st=students.find(s=>s.name===x.student);const msg=`Olá, ${x.student}! 💜 Abriu uma vaga no horário de ${x.time}, que estava entre suas preferências na Power Fit Studio. Você tem até 20 minutos para confirmar se deseja ficar com a vaga. Responda SIM para confirmar ou NÃO para recusar.`;window.open(`https://wa.me/${String(st?.phone||'').replace(/\D/g,'')}?text=${encodeURIComponent(msg)}`,'_blank');setWaitlist(w=>({...w,[x.time]:(w[x.time]||[]).filter(y=>y.student!==x.student)}));notify('WhatsApp aberto com a convocação padronizada.');};return <div className="admin-pad"><div className="admin-title"><div><span>LISTA DE ESPERA</span><h1>Vagas e prioridade</h1><p>Quando surgir uma vaga, a recepção convoca o próximo aluno.</p></div></div>{all.length?all.map((x,i)=><div className="wait-row" key={x.time+x.student}><div className="rank">{i+1}</div><span><b>{x.student}</b><small>{x.time} • frequência {x.score}%</small></span><em>Prioridade alta</em><button onClick={()=>call(x)}>Convocar</button></div>):<div className="empty">Nenhum aluno aguardando.</div>}<div className="card rule-card"><ListChecks/><div><b>Convocação automática</b><span>Ao clicar em Convocar, o WhatsApp abre com a mensagem e o prazo de 20 minutos para confirmação.</span></div></div></div>}
function Reports({students,teachers,bookings,retentionActions,setRetentionActions}){const action=(s)=>{const now=new Date().toLocaleString('pt-BR');setRetentionActions(x=>({...x,[s.id]:{...(x[s.id]||{}),contactedAt:now}}));window.open(`${waLink(s.phone)}?text=${encodeURIComponent(`Olá, ${s.name}! Aqui é da Power Fit Studio. Sentimos sua falta e queremos saber como podemos te ajudar a manter sua rotina de treinos. 💜`)}`,'_blank');};return <div className="admin-pad"><div className="admin-title"><div><span>RELATÓRIOS</span><h1>Indicadores da academia</h1><p>Visão de operação, retenção e relacionamento.</p></div></div><div className="report-card"><h3>Frequência por mês</h3><div className="bars">{[62,70,68,76,73,79,82].map((x,i)=><div key={i}><i style={{height:`${x}%`}}/><small>{['Mar','Abr','Mai','Jun','Jul','Ago','Set'][i]}</small></div>)}</div></div><div className="report-grid"><Report label="Alunos ativos" value={students.filter(s=>s.status==='Ativo').length} trend="+6%"/><Report label="Taxa de retenção" value="92%" trend="+1,8%"/><Report label="Ocupação média" value="78%" trend="+5%"/><Report label="Satisfação" value="4,7/5" trend="+0,3"/></div><div className="card report-list"><h3>Oportunidades de retenção</h3>{students.filter(s=>s.frequency<70).map(s=>{const a=retentionActions[s.id]||{};return <div key={s.id}><TrendingDown/><span><b>{s.name}</b><small>Frequência caiu para {s.frequency}%</small>{a.contactedAt&&<small>Acionado em {a.contactedAt}</small>}<textarea value={a.observation||''} onChange={e=>setRetentionActions(x=>({...x,[s.id]:{...(x[s.id]||{}),observation:e.target.value}}))} placeholder="Observação / retorno do aluno..."/></span><button onClick={()=>action(s)}>Acionar</button></div>})}</div></div>}
function Report({label,value,trend}){return <div className="report-mini"><small>{label}</small><b>{value}</b><em>{trend}</em></div>}
function SettingsAdmin({teachers,setTeachers}){const [cancel,setCancel]=useState(2);return <div className="admin-pad"><div className="admin-title"><div><span>CONFIGURAÇÕES</span><h1>Regras da academia</h1><p>Parâmetros que controlam a operação do Power Fit.</p></div></div><div className="settings-list"><div><Users/><span><b>Capacidade por professor</b><small>Máximo de alunos por professor por horário</small></span><strong>4</strong></div><div><Clock3/><span><b>Antecedência para cancelar</b><small>Treino não contabiliza falta até o prazo definido</small></span><input type="number" value={cancel} onChange={e=>setCancel(e.target.value)}/><b>h</b></div><div><Zap/><span><b>Recalcular capacidade automaticamente</b><small>Escala dos professores altera as vagas</small></span><span className="toggle on">●</span></div><div><CreditCard/><span><b>Bloqueio por inadimplência</b><small>Impede novos agendamentos até identificação do pagamento</small></span><span className="toggle on">●</span></div><div><UserCheck/><span><b>Professor sugerido por histórico</b><small>Prioriza o professor com maior número de treinos anteriores</small></span><span className="toggle on">●</span></div></div></div>}
function Modal({type,onClose,onSave}){const [name,setName]=useState('');const [kind,setKind]=useState('Day use');const [value,setValue]=useState('20');const [phone,setPhone]=useState('');const [email,setEmail]=useState('');const [address,setAddress]=useState('');const [cpf,setCpf]=useState('');const [profession,setProfession]=useState('');const [role,setRole]=useState('Professor');const [slots,setSlots]=useState(['18:00']);const [hireDate,setHireDate]=useState('');const [contractType,setContractType]=useState('CLT');const [teacherPhone,setTeacherPhone]=useState('');const [teacherEmail,setTeacherEmail]=useState('');const [teacherCpf,setTeacherCpf]=useState('');if(type==='payment')return <div className="modal-back"><div className="modal"><button onClick={onClose}><X/></button><span className="eyebrow">POWER FIT • RECEPÇÃO</span><h2>Inserir pagamento</h2><label>Nome do aluno<input value={name} onChange={e=>setName(e.target.value)} placeholder="Nome do aluno"/></label><label>Tipo<select value={kind} onChange={e=>{setKind(e.target.value);setValue(e.target.value==='Day use'?'20':e.target.value==='Experimental'?'0':'149.90')}}><option>Pagamento mensalidade</option><option>Day use</option><option>Experimental</option></select></label><label>Valor<input value={value} onChange={e=>setValue(e.target.value)} /></label><button className="primary-btn full" onClick={()=>{onSave?.({name,type:kind,value});onClose()}}>REGISTRAR PAGAMENTO <Check/></button></div></div>;if(type==='newStudent')return <div className="modal-back"><div className="modal"><button onClick={onClose}><X/></button><span className="eyebrow">POWER FIT • RECEPÇÃO</span><h2>Novo aluno</h2><label>Nome completo<input value={name} onChange={e=>setName(e.target.value)} /></label><div className="two"><label>Telefone<input value={phone} onChange={e=>setPhone(e.target.value)} /></label><label>E-mail<input value={email} onChange={e=>setEmail(e.target.value)} /></label></div><label>Endereço<input value={address} onChange={e=>setAddress(e.target.value)} /></label><div className="two"><label>CPF<input value={cpf} onChange={e=>setCpf(e.target.value)} /></label><label>Profissão<input value={profession} onChange={e=>setProfession(e.target.value)} /></label></div><label>Modalidade<select value={kind} onChange={e=>setKind(e.target.value)}><option>Plano Mensal</option><option>TotalPass</option><option>Wellhub</option></select></label><button className="primary-btn full" onClick={()=>{onSave?.({name:name||'Novo aluno',phone,email,address,cpf,profession,plan:kind,payment:'pago',paymentStatus:'identified',status:'Ativo',birthday:'1990-01-01',due:'10/10/2026',value:149.9,height:1.65,weight:0,goal:0,initialWeight:0,frequency:0,monthlyWorkouts:0});onClose()}}>CADASTRAR ALUNO <Check/></button></div></div>;if(type==='newTeacher')return <div className="modal-back"><div className="modal"><button onClick={onClose}><X/></button><span className="eyebrow">POWER FIT • EQUIPE</span><h2>Novo professor / estagiário</h2><label>Nome completo<input value={name} onChange={e=>setName(e.target.value)} /></label><div className="two"><label>Função<select value={role} onChange={e=>setRole(e.target.value)}><option>Professor</option><option>Estagiário</option></select></label><label>Contrato<select value={contractType} onChange={e=>setContractType(e.target.value)}><option>CLT</option><option>Estágio</option><option>Prestador</option></select></label></div><div className="two"><label>Telefone<input value={teacherPhone} onChange={e=>setTeacherPhone(e.target.value)} /></label><label>E-mail<input value={teacherEmail} onChange={e=>setTeacherEmail(e.target.value)} /></label></div><label>CPF<input value={teacherCpf} onChange={e=>setTeacherCpf(e.target.value)} /></label><label>Data de contratação<input type="date" value={hireDate} onChange={e=>setHireDate(e.target.value)} /></label><label>Horários disponíveis</label><div className="slot-checks">{TIMES.map(t=><label key={t}><input type="checkbox" checked={slots.includes(t)} onChange={e=>setSlots(x=>e.target.checked?[...x,t]:x.filter(v=>v!==t))}/>{t}</label>)}</div><button className="primary-btn full" onClick={()=>{onSave?.({id:Date.now(),name:name||'Novo profissional',active:true,slots,role,hireDate,contractType,phone:teacherPhone,email:teacherEmail,cpf:teacherCpf});onClose()}}>CADASTRAR PROFISSIONAL <Check/></button></div></div>;return null}
class AppErrorBoundary extends React.Component{constructor(props){super(props);this.state={error:null}}static getDerivedStateFromError(error){return {error}}componentDidCatch(error,info){console.error('Power Fit runtime error',error,info)}render(){if(this.state.error)return <div style={{minHeight:'100vh',padding:'32px',background:'#0d0718',color:'#fff',fontFamily:'Arial'}}><h2>Não foi possível abrir esta área</h2><p>O aplicativo encontrou um erro inesperado. Volte para o aluno e tente novamente.</p><button onClick={()=>{this.setState({error:null});location.reload()}} style={{padding:'12px 18px',borderRadius:'10px',border:0,cursor:'pointer'}}>Recarregar aplicativo</button></div>;return this.props.children}}
createRoot(document.getElementById('root')).render(<AppErrorBoundary><App/></AppErrorBoundary>);
